class NetworkConfig {
    int attempts;
    int delay_ms;
public:
    // Explicit constructor prevents implicit conversion
    // Default parameters provide flexible initialization
    explicit NetworkConfig(int a = 3, int d = 500)
        : attempts(a), delay_ms(d) {}
};

